     8	import io.javalin.Javalin;
     9	import java.math.BigDecimal;
    10	import java.sql.SQLException;
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.util.List;
    14	import java.util.Map;
    15	import java.util.stream.Collectors;
    16	
    17	public class ReportAPI {
    18	    public static void register(Javalin app) {
    19	        app.get("/reports/occupancy", ctx -> getOccupancyReport(ctx));
    20	        app.get("/reports/revenue", ctx -> getRevenueReport(ctx));
    21	    }
    22	
    23	    private static void getOccupancyReport(io.javalin.http.Context ctx) {
    24	        try {
    25	            String dateParam = ctx.queryParam("date");
    26	            if (dateParam == null || dateParam.isEmpty()) {
    27	                ctx.status(400);
    28	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
    29	                return;
    30	            }
    31	
    32	            LocalDate date;
    33	            try {
    34	                date = DateFormatter.parseISO(dateParam);
    35	            } catch (Exception e) {
    36	                ctx.status(400);
    37	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    38	                return;
    39	            }
    40	
    41	            List<Room> allRooms = RoomService.getAllRooms();
    42	            List<Reservation> reservations = ReservationService.getReservationsByDate(date);
    43	
    44	            Map<Integer, Reservation> reservationsByRoom = reservations.stream()
    45	                .collect(Collectors.toMap(r -> r.roomNumber, r -> r));
    46	
    47	            StringBuilder csv = new StringBuilder();
    48	            csv.append("room,type,reservation,check_in,check_out\n");
    49	
    50	            int occupiedCount = 0;
    51	            for (Room room : allRooms) {
    52	                if (reservationsByRoom.containsKey(room.number)) {
    53	                    Reservation res = reservationsByRoom.get(room.number);
    54	                    csv.append(res.roomNumber).append(",")
    55	                       .append(room.type).append(",")
    56	                       .append(res.id).append(",")
    57	                       .append(DateFormatter.formatISO(res.checkIn)).append(",")
    58	                       .append(DateFormatter.formatISO(res.checkOut)).append("\n");
    59	                    occupiedCount++;
    60	                }
    61	            }
    62	
    63	            csv.append("total,").append(occupiedCount).append("/").append(allRooms.size()).append("\n");
    64	
    65	            ctx.contentType("text/csv;charset=utf-8");
    66	            ctx.result(csv.toString());
    67	        } catch (SQLException e) {
    68	            ctx.status(500);
    69	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
    70	        }
    71	    }
    72	
    73	    private static void getRevenueReport(io.javalin.http.Context ctx) {
    74	        try {
    75	            String monthParam = ctx.queryParam("month");
    76	            if (monthParam == null || monthParam.isEmpty()) {
    77	                ctx.status(400);
    78	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
    79	                return;
    80	            }
    81	
    82	            LocalDate monthStart;
    83	            try {
    84	                YearMonth ym = YearMonth.parse(monthParam);
    85	                monthStart = ym.atDay(1);
    86	            } catch (Exception e) {
    87	                ctx.status(400);
    88	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
    89	                return;
    90	            }
    91	
    92	            List<Reservation> reservations = ReservationService.getReservationsByMonth(monthStart);
    93	
    94	            StringBuilder csv = new StringBuilder();
    95	            csv.append("reservation,room,check_in,check_out,status,amount\n");
    96	
    97	            BigDecimal totalAmount = BigDecimal.ZERO;
    98	            for (Reservation res : reservations) {
    99	                BigDecimal amount = res.amountPaid;
   100	                if (res.refund != null && res.refund.compareTo(BigDecimal.ZERO) > 0) {
   101	                    amount = amount.subtract(res.refund);
   102	                }
   103	
   104	                csv.append(res.id).append(",")
   105	                   .append(res.roomNumber).append(",")
   106	                   .append(DateFormatter.formatISO(res.checkIn)).append(",")
   107	                   .append(DateFormatter.formatISO(res.checkOut)).append(",")
   108	                   .append(res.status).append(",")
   109	                   .append(String.format("%.2f", amount)).append("\n");
   110	
   111	                totalAmount = totalAmount.add(amount);
   112	            }
   113	
   114	            csv.append("total,,,,").append(String.format("%.2f", totalAmount)).append("\n");
   115	
   116	            ctx.contentType("text/csv;charset=utf-8");
   117	            ctx.result(csv.toString());
   118	        } catch (SQLException e) {
   119	            ctx.status(500);
   120	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
   121	        }
   122	    }
   123	
   124	    static class ErrorResponse {
   125	        public String error;
   126	        public String message;
   127	
   128	        ErrorResponse(String error, String message) {
   129	            this.error = error;
   130	            this.message = message;
   131	        }
   132	    }
   133	}
