    18	    public static void register(Javalin app) {
    19	        app.post("/reservations", ctx -> createReservation(ctx));
    20	        app.get("/reservations/{id}", ctx -> getReservation(ctx));
    21	        app.post("/reservations/{id}/confirmation", ctx -> confirmReservation(ctx));
    22	        app.post("/reservations/{id}/cancellation", ctx -> cancelReservation(ctx));
