    28	    private static void createReservation(io.javalin.http.Context ctx) {
    29	        try {
    30	            JsonNode body = mapper.readTree(ctx.body());
    31	
    32	            Integer roomNumber = getIntField(body, "roomNumber");
    33	            String guestName = getStringField(body, "guestName");
    34	            String guestEmail = getStringField(body, "guestEmail");
    35	            String guestCpf = getStringField(body, "guestCpf");
    36	            String checkInStr = getStringField(body, "checkIn");
    37	            String checkOutStr = getStringField(body, "checkOut");
    38	            Integer guests = getIntField(body, "guests");
    39	            String ratePlan = getStringField(body, "ratePlan");
    40	            String companyCode = body.has("companyCode") ? body.get("companyCode").asText() : null;
    41	
    42	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
    43	                checkInStr == null || checkOutStr == null || guests == null || ratePlan == null) {
    44	                ctx.status(400);
    45	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
    46	                return;
    47	            }
    48	
    49	            LocalDate checkIn = DateFormatter.parseISO(checkInStr);
    50	            LocalDate checkOut = DateFormatter.parseISO(checkOutStr);
    51	
    52	            Room room = RoomService.getRoomByNumber(roomNumber);
    53	            if (room == null) {
    54	                ctx.status(404);
    55	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
    56	                return;
    57	            }
    58	
    59	            Validator.ValidationError validationError = Validator.validateReservationRequest(
    60	                roomNumber, checkIn, checkOut, guests, ratePlan, companyCode, room.capacity);
    61	
    62	            if (validationError != null) {
    63	                ctx.status("CAPACITY_EXCEEDED".equals(validationError.code) ? 422 : 400);
    64	                ctx.json(new ErrorResponse(validationError.code, validationError.message));
    65	                return;
    66	            }
    67	
    68	            if (!ReservationService.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    69	                ctx.status(409);
    70	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
    71	                return;
    72	            }
    73	
    74	            var pricingResult = RatePlanCalculator.calculate(
    75	                ratePlan, roomNumber, room.nightlyRate, checkIn, checkOut, guests, companyCode);
    76	
    77	            Reservation reservation = ReservationService.createReservation(
    78	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode,
    79	                pricingResult.subtotal, pricingResult.discount, pricingResult.total, pricingResult.nights);
    80	
    81	            ctx.status(201);
    82	            ctx.json(reservation);
    83	        } catch (Exception e) {
    84	            ctx.status(400);
    85	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
    86	        }
    87	    }
