    89	    private static void getReservation(io.javalin.http.Context ctx) {
    90	        try {
    91	            int id = Integer.parseInt(ctx.pathParam("id"));
    92	            Reservation reservation = ReservationService.getReservationById(id);
    93	
    94	            if (reservation == null) {
    95	                ctx.status(404);
    96	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
    97	                return;
    98	            }
    99	
   100	            ctx.json(reservation);
   101	        } catch (NumberFormatException e) {
   102	            ctx.status(404);
   103	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   104	        } catch (SQLException e) {
   105	            ctx.status(500);
   106	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
   107	        }
   108	    }
   109	
   110	    private static void confirmReservation(io.javalin.http.Context ctx) {
   111	        try {
   112	            int id = Integer.parseInt(ctx.pathParam("id"));
   113	            Reservation reservation = ReservationService.getReservationById(id);
   114	
   115	            if (reservation == null) {
   116	                ctx.status(404);
   117	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   118	                return;
   119	            }
   120	
   121	            if (!"PENDING".equals(reservation.status)) {
   122	                ctx.status(409);
   123	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Reservation cannot be confirmed from this status"));
   124	                return;
   125	            }
   126	
   127	            ReservationService.confirmReservation(id, reservation.total);
   128	
   129	            Receipt receipt = ReceiptService.createReceipt(reservation);
   130	            String receiptText = ReceiptService.formatReceipt(receipt);
   131	            String emailBody = ReceiptService.createConfirmationEmail(reservation.guestName, receipt);
   132	
   133	            MessageService.sendMessage("EMAIL", reservation.guestEmail, "Reserva confirmada - Pousada Maré Alta", emailBody);
   134	
   135	            reservation = ReservationService.getReservationById(id);
   136	            ctx.json(reservation);
   137	        } catch (NumberFormatException e) {
   138	            ctx.status(404);
   139	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   140	        } catch (SQLException e) {
   141	            ctx.status(500);
   142	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
   143	        }
   144	    }
