   146	    private static void cancelReservation(io.javalin.http.Context ctx) {
   147	        try {
   148	            int id = Integer.parseInt(ctx.pathParam("id"));
   149	            Reservation reservation = ReservationService.getReservationById(id);
   150	
   151	            if (reservation == null) {
   152	                ctx.status(404);
   153	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   154	                return;
   155	            }
   156	
   157	            if (!("PENDING".equals(reservation.status) || "CONFIRMED".equals(reservation.status))) {
   158	                ctx.status(409);
   159	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Reservation cannot be cancelled from this status"));
   160	                return;
   161	            }
   162	
   163	            BigDecimal refundAmount = RatePlanCalculator.getRefundAmount(reservation.ratePlan, reservation.amountPaid);
   164	            ReservationService.refundReservation(id, refundAmount);
   165	
   166	            reservation = ReservationService.getReservationById(id);
   167	            ctx.json(reservation);
   168	        } catch (NumberFormatException e) {
   169	            ctx.status(404);
   170	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   171	        } catch (SQLException e) {
   172	            ctx.status(500);
   173	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
   174	        }
   175	    }
