   177	    private static void checkIn(io.javalin.http.Context ctx) {
   178	        try {
   179	            int id = Integer.parseInt(ctx.pathParam("id"));
   180	            Reservation reservation = ReservationService.getReservationById(id);
   181	
   182	            if (reservation == null) {
   183	                ctx.status(404);
   184	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   185	                return;
