   194	            ReservationService.updateReservationStatus(id, "CHECKED_IN");
   195	            reservation = ReservationService.getReservationById(id);
   196	            ctx.json(reservation);
   197	        } catch (NumberFormatException e) {
   198	            ctx.status(404);
   199	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   200	        } catch (SQLException e) {
   201	            ctx.status(500);
   202	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Database error"));
   203	        }
   204	    }
