   206	    private static void checkOut(io.javalin.http.Context ctx) {
   207	        try {
   208	            int id = Integer.parseInt(ctx.pathParam("id"));
   209	            Reservation reservation = ReservationService.getReservationById(id);
   210	
   211	            if (reservation == null) {
   212	                ctx.status(404);
   213	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   214	                return;
   215	            }
   216	
   217	            if (!"CHECKED_IN".equals(reservation.status)) {
   218	                ctx.status(409);
