    24	    public static PricingResult calculate(String ratePlan, int roomNumber, BigDecimal nightlyRate,
    25	                                         LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    26	        return switch (ratePlan) {
    27	            case "STANDARD" -> calculateStandard(nightlyRate, checkIn, checkOut);
    28	            case "NON_REFUNDABLE" -> calculateNonRefundable(nightlyRate, checkIn, checkOut);
    29	            case "CORPORATE" -> calculateCorporate(nightlyRate, checkIn, checkOut, companyCode);
