    36	    private static PricingResult calculateStandard(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
    37	        int nights = (int) checkIn.until(checkOut).getDays();
    38	        BigDecimal subtotal = BigDecimal.ZERO;
    39	
    40	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    41	            BigDecimal rate = nightlyRate;
    42	            if (SeasonUtils.isHighSeason(date)) {
    43	                rate = PriceCalculator.multiply(rate, new BigDecimal("1.20"));
    44	            }
    45	            subtotal = PriceCalculator.add(subtotal, rate);
    46	        }
    47	
    48	        return new PricingResult(subtotal, BigDecimal.ZERO, subtotal, nights);
    49	    }
