    62	
    63	        BigDecimal discount = PriceCalculator.percentage(subtotal, 15);
    64	        BigDecimal total = PriceCalculator.subtract(subtotal, discount);
    65	
    66	        return new PricingResult(subtotal, discount, total, nights);
