     6	public class Validator {
     7	    public static class ValidationError {
     8	        public String code;
     9	        public String message;
    10	
    11	        public ValidationError(String code, String message) {
    12	            this.code = code;
    13	            this.message = message;
    14	        }
    15	    }
    16	
    17	    public static ValidationError validateReservationRequest(
    18	            int roomNumber, LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan, String companyCode, int roomCapacity) {
    19	
    20	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    21	            return new ValidationError("INVALID_REQUEST", "Check-out date must be after check-in date");
    22	        }
    23	
    24	        if (guests < 1) {
    25	            return new ValidationError("INVALID_REQUEST", "At least 1 guest is required");
    26	        }
    27	
    28	        if (guests > roomCapacity) {
    29	            return new ValidationError("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
    30	        }
    31	
    32	        if (ratePlan == null || ratePlan.isEmpty()) {
    33	            return new ValidationError("INVALID_REQUEST", "Rate plan is required");
    34	        }
    35	
    36	        if (!isValidRatePlan(ratePlan)) {
    37	            return new ValidationError("INVALID_REQUEST", "Invalid rate plan: " + ratePlan);
    38	        }
    39	
    40	        if ("CORPORATE".equals(ratePlan)) {
    41	            if (companyCode == null || companyCode.isEmpty()) {
    42	                return new ValidationError("INVALID_REQUEST", "Company code is required for CORPORATE rate plan");
    43	            }
    44	            if (!isValidCompanyCode(companyCode)) {
    45	                return new ValidationError("INVALID_REQUEST", "Invalid company code: " + companyCode);
    46	            }
    47	        }
    48	
    49	        if ("WEEKEND_PACKAGE".equals(ratePlan)) {
    50	            ValidationError weekendError = validateWeekendPackage(checkIn, checkOut);
    51	            if (weekendError != null) {
    52	                return weekendError;
    53	            }
    54	        }
    55	
    56	        if ("LONG_STAY".equals(ratePlan)) {
    57	            long nights = checkIn.until(checkOut).getDays();
    58	            if (nights < 7) {
    59	                return new ValidationError("INVALID_REQUEST", "Long stay requires at least 7 nights");
    60	            }
    61	        }
    62	
    63	        return null;
    64	    }
    65	
    66	    private static ValidationError validateWeekendPackage(LocalDate checkIn, LocalDate checkOut) {
    67	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    68	            return new ValidationError("INVALID_REQUEST", "Weekend package must start on Friday");
    69	        }
    70	
    71	        if (checkOut.getDayOfWeek() != DayOfWeek.MONDAY) {
    72	            return new ValidationError("INVALID_REQUEST", "Weekend package must end on Sunday (checkout Monday)");
    73	        }
    74	
    75	        long nights = checkIn.until(checkOut).getDays();
    76	        if (nights != 2) {
    77	            return new ValidationError("INVALID_REQUEST", "Weekend package must be exactly 2 nights");
    78	        }
    79	
    80	        return null;
    81	    }
    82	
    83	    private static boolean isValidRatePlan(String ratePlan) {
    84	        return switch (ratePlan) {
    85	            case "STANDARD", "NON_REFUNDABLE", "CORPORATE", "WEEKEND_PACKAGE", "LONG_STAY" -> true;
    86	            default -> false;
    87	        };
    88	    }
    89	
    90	    private static boolean isValidCompanyCode(String companyCode) {
    91	        return switch (companyCode.toUpperCase()) {
    92	            case "TECNOSUL", "AGROVALE", "FARMAVIDA" -> true;
    93	            default -> false;
    94	        };
    95	    }
    96	}
