     9	public class RatePlanCalculator {
    10	    public static class PricingResult {
    11	        public BigDecimal subtotal;
    12	        public BigDecimal discount;
    13	        public BigDecimal total;
    14	        public int nights;
    15	
    16	        public PricingResult(BigDecimal subtotal, BigDecimal discount, BigDecimal total, int nights) {
    17	            this.subtotal = subtotal;
    18	            this.discount = discount;
    19	            this.total = total;
    20	            this.nights = nights;
    21	        }
    22	    }
    23	
    24	    public static PricingResult calculate(String ratePlan, int roomNumber, BigDecimal nightlyRate,
    25	                                         LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    26	        return switch (ratePlan) {
    27	            case "STANDARD" -> calculateStandard(nightlyRate, checkIn, checkOut);
    28	            case "NON_REFUNDABLE" -> calculateNonRefundable(nightlyRate, checkIn, checkOut);
    29	            case "CORPORATE" -> calculateCorporate(nightlyRate, checkIn, checkOut, companyCode);
    30	            case "WEEKEND_PACKAGE" -> calculateWeekendPackage(roomNumber, checkIn, checkOut);
    31	            case "LONG_STAY" -> calculateLongStay(nightlyRate, checkIn, checkOut);
    32	            default -> throw new IllegalArgumentException("Unknown rate plan: " + ratePlan);
    33	        };
    34	    }
    35	
    36	    private static PricingResult calculateStandard(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
    37	        int nights = (int) checkIn.until(checkOut).getDays();
    38	        BigDecimal subtotal = BigDecimal.ZERO;
    39	
    40	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    41	            BigDecimal rate = nightlyRate;
    42	            if (SeasonUtils.isHighSeason(date)) {
    43	                rate = PriceCalculator.multiply(rate, new BigDecimal("1.20"));
    44	            }
    45	            subtotal = PriceCalculator.add(subtotal, rate);
    46	        }
    47	
    48	        return new PricingResult(subtotal, BigDecimal.ZERO, subtotal, nights);
    49	    }
    50	
    51	    private static PricingResult calculateNonRefundable(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
    52	        int nights = (int) checkIn.until(checkOut).getDays();
    53	        BigDecimal subtotal = BigDecimal.ZERO;
    54	
    55	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    56	            BigDecimal rate = nightlyRate;
    57	            if (SeasonUtils.isHighSeason(date)) {
    58	                rate = PriceCalculator.multiply(rate, new BigDecimal("1.20"));
    59	            }
    60	            subtotal = PriceCalculator.add(subtotal, rate);
    61	        }
    62	
    63	        BigDecimal discount = PriceCalculator.percentage(subtotal, 15);
    64	        BigDecimal total = PriceCalculator.subtract(subtotal, discount);
    65	
    66	        return new PricingResult(subtotal, discount, total, nights);
    67	    }
    68	
    69	    private static PricingResult calculateCorporate(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    70	        int discountPercent = getCompanyDiscount(companyCode);
    71	        int nights = (int) checkIn.until(checkOut).getDays();
    72	        BigDecimal subtotal = BigDecimal.ZERO;
    73	
    74	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    75	            BigDecimal rate = nightlyRate;
    76	            if (SeasonUtils.isHighSeason(date)) {
    77	                rate = PriceCalculator.multiply(rate, new BigDecimal("1.20"));
    78	            }
    79	            subtotal = PriceCalculator.add(subtotal, rate);
    80	        }
    81	
    82	        BigDecimal discount = PriceCalculator.percentage(subtotal, discountPercent);
    83	        BigDecimal total = PriceCalculator.subtract(subtotal, discount);
    84	
    85	        return new PricingResult(subtotal, discount, total, nights);
    86	    }
    87	
    88	    private static PricingResult calculateWeekendPackage(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    89	        BigDecimal packagePrice = getWeekendPackagePrice(roomNumber);
    90	        int nights = (int) checkIn.until(checkOut).getDays();
    91	
    92	        return new PricingResult(packagePrice, BigDecimal.ZERO, packagePrice, nights);
    93	    }
    94	
    95	    private static PricingResult calculateLongStay(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut) {
    96	        int nights = (int) checkIn.until(checkOut).getDays();
    97	        BigDecimal subtotal = BigDecimal.ZERO;
    98	
    99	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
   100	            BigDecimal rate = nightlyRate;
   101	            if (SeasonUtils.isHighSeason(date)) {
   102	                rate = PriceCalculator.multiply(rate, new BigDecimal("1.20"));
   103	            }
   104	            subtotal = PriceCalculator.add(subtotal, rate);
   105	        }
   106	
   107	        BigDecimal discount = PriceCalculator.percentage(subtotal, 10);
   108	        BigDecimal total = PriceCalculator.subtract(subtotal, discount);
   109	
   110	        return new PricingResult(subtotal, discount, total, nights);
   111	    }
   112	
   113	    private static int getCompanyDiscount(String companyCode) {
   114	        return switch (companyCode) {
   115	            case "TECNOSUL" -> 12;
   116	            case "AGROVALE" -> 18;
   117	            case "FARMAVIDA" -> 25;
   118	            default -> throw new IllegalArgumentException("Unknown company code: " + companyCode);
   119	        };
   120	    }
   121	
   122	    private static BigDecimal getWeekendPackagePrice(int roomNumber) {
   123	        return switch (roomNumber) {
   124	            case 101, 102 -> new BigDecimal("520.00");
   125	            case 201, 202 -> new BigDecimal("820.00");
   126	            case 301 -> new BigDecimal("1200.00");
   127	            default -> throw new IllegalArgumentException("Unknown room: " + roomNumber);
   128	        };
   129	    }
   130	
   131	    public static BigDecimal getRefundAmount(String ratePlan, BigDecimal amountPaid) {
   132	        return switch (ratePlan) {
   133	            case "STANDARD", "CORPORATE", "LONG_STAY" -> amountPaid;
   134	            case "NON_REFUNDABLE" -> BigDecimal.ZERO;
   135	            case "WEEKEND_PACKAGE" -> PriceCalculator.divide(amountPaid, new BigDecimal("2"));
   136	            default -> throw new IllegalArgumentException("Unknown rate plan: " + ratePlan);
   137	        };
   138	    }
   139	}
