    13	        Room room = RoomService.getRoomByNumber(reservation.roomNumber);
    14	        return new Receipt(
    15	            reservation.id,
    16	            reservation.guestName,
    17	            reservation.guestCpf,
    18	            reservation.roomNumber,
    19	            room.type,
    20	            reservation.checkIn,
