    29	    public static String formatReceipt(Receipt receipt) {
    30	        StringBuilder sb = new StringBuilder();
    31	        sb.append("Comprovante de reserva nº ").append(receipt.reservationId).append("\n");
    32	        sb.append("Hóspede: ").append(receipt.guestName).append(" (CPF ").append(receipt.guestCpf).append(")\n");
    33	        sb.append("Quarto: ").append(receipt.roomNumber).append(" (").append(receipt.roomType).append(")\n");
    34	        sb.append("Entrada: ").append(DateFormatter.formatDisplay(receipt.checkIn))
    35	          .append(" | Saída: ").append(DateFormatter.formatDisplay(receipt.checkOut))
    36	          .append(" | ").append(receipt.nights).append(receipt.nights == 1 ? " diária" : " diárias").append("\n");
    37	        sb.append("Diárias: ").append(formatCurrency(receipt.subtotal)).append("\n");
    38	
    39	        if (receipt.discount.compareTo(BigDecimal.ZERO) > 0) {
    40	            sb.append("Desconto: ").append(formatCurrency(receipt.discount)).append("\n");
    41	        }
    42	
    43	        sb.append("Total: ").append(formatCurrency(receipt.total)).append("\n");
    44	
    45	        return sb.toString();
    46	    }
