    51	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    52	        sb.append(formatReceipt(receipt));
    53	        sb.append("\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
    54	        sb.append("Até breve!\n");
    55	
    56	        return sb.toString();
    57	    }
    58	
    59	    public static String formatCurrency(BigDecimal amount) {
    60	        String formatted = String.format("%.2f", amount);
    61	        String[] parts = formatted.split("\\.");
    62	        StringBuilder result = new StringBuilder();
    63	        int len = parts[0].length();
    64	        for (int i = 0; i < len; i++) {
    65	            if (i > 0 && (len - i) % 3 == 0) {
    66	                result.append(".");
    67	            }
    68	            result.append(parts[0].charAt(i));
    69	        }
    70	        return "R$ " + result.toString() + "," + parts[1];
    71	    }
