     6	public class PriceCalculator {
     7	    private static final int SCALE = 2;
     8	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
     9	
    10	    public static BigDecimal round(BigDecimal value) {
    11	        return value.setScale(SCALE, ROUNDING_MODE);
    12	    }
    13	
    14	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
    15	        return round(a.multiply(b));
    16	    }
    17	
    18	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
    19	        return round(a.divide(b, SCALE, ROUNDING_MODE));
    20	    }
    21	
    22	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
    23	        return round(a.add(b));
    24	    }
    25	
    26	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
    27	        return round(a.subtract(b));
    28	    }
    29	
    30	    public static BigDecimal percentage(BigDecimal value, int percent) {
    31	        return multiply(value, new BigDecimal(percent).divide(new BigDecimal(100), SCALE, ROUNDING_MODE));
    32	    }
    33	}
